def transform(grid):
    out = [row[:] for row in grid]
    n = 5
    frame = grid[0][0]

    # The first panel has a common fill color and a rarer color that marks
    # the dividing line and a point indicating which side gets panel B.
    panel = [grid[r + 1][c + 1] for r in range(n) for c in range(n)]
    counts = {}
    for v in panel:
        if v != frame:
            counts[v] = counts.get(v, 0) + 1
    key = min(counts, key=counts.get)
    key_cells = {
        (r, c) for r in range(n) for c in range(n)
        if grid[r + 1][c + 1] == key
    }

    # The largest connected component of the key color is the divider.
    components = []
    remaining = set(key_cells)
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    q = (r + dr, c + dc)
                    if q in remaining:
                        remaining.remove(q)
                        comp.add(q)
                        stack.append(q)
        components.append(comp)

    divider = max(components, key=len)
    markers = key_cells - divider

    # Label the areas on either side of the divider.
    labels = {}
    label_sizes = {}
    next_label = 0
    for r in range(n):
        for c in range(n):
            if (r, c) in divider or (r, c) in labels:
                continue
            stack = [(r, c)]
            labels[(r, c)] = next_label
            size = 0
            while stack:
                rr, cc = stack.pop()
                size += 1
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    q = (rr + dr, cc + dc)
                    if (0 <= q[0] < n and 0 <= q[1] < n
                            and q not in divider and q not in labels):
                        labels[q] = next_label
                        stack.append(q)
            label_sizes[next_label] = size
            next_label += 1

    marker_labels = [labels[p] for p in markers if p in labels]
    if marker_labels:
        marker_side = max(set(marker_labels), key=marker_labels.count)
    elif label_sizes:
        marker_side = max(label_sizes, key=label_sizes.get)
    else:
        marker_side = 0

    # The background is the most common color in the two motif panels.
    source_cells = [
        grid[r + 1][c]
        for r in range(n) for c in range(7, 12)
    ] + [
        grid[r + 1][c]
        for r in range(n) for c in range(13, 18)
    ]
    source_counts = {}
    for v in source_cells:
        source_counts[v] = source_counts.get(v, 0) + 1
    base = max(source_counts, key=source_counts.get)

    # Copy B on the marker side, C on the opposite side. On the divider,
    # combine both motifs, preferring a non-background B cell when present.
    for r in range(n):
        for c in range(n):
            b = grid[r + 1][7 + c]
            cc = grid[r + 1][13 + c]

            if (r, c) in divider:
                value = b if b != base else cc
            elif labels.get((r, c)) == marker_side:
                value = b
            else:
                value = cc

            out[r + 1][19 + c] = value

    return out
